         let tracked ticket = ticket.tracked_unwrap();
         let tracked batch_perm = batch_perms.tracked_unwrap();
         (
             response.0,
             ThreadToken {
                 rid,
                 tid,
                 fc_client: Tracked(fc_clients),
                 batch_perm: Tracked(batch_perm),
             },
             Tracked(ticket),
         )
