         &&& self.replica.key() == nid
         &&& self.replica.instance_id() == self.unbounded_log_instance.id()
         &&& self.combiner.value().is_Ready()
         &&& self.combiner.key() == nid
         &&& self.cb_combiner.key() == nid
         &&& self.cb_combiner.value().is_Idle()
